import{_ as r,o as a,c as o,a2 as s}from"./chunks/framework.BXzK3EA4.js";const n="/assets/323_76456de3-bc90-4fd4-8778-fc3e4d693453.kVL1ZYNS.png",e="/assets/324_eb05044d-9662-4d5d-8ea9-029eb453ec58.Dpc5NOxV.png",l="/assets/325_9d3c0a0b-c444-4201-8be9-a1ea26cef370.BjDBF8Oo.png",_=JSON.parse('{"title":"如何查找已购买的产品","description":"","frontmatter":{"title":"如何查找已购买的产品"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/find-purchased-products.md","filePath":"ops-knowledge-base/presales-support/find-purchased-products.md","lastUpdated":1788259091000}'),d={name:"ops-knowledge-base/presales-support/find-purchased-products.md"};function i(g,t,h,p,c,u){return a(),o("div",null,[...t[0]||(t[0]=[s('<h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>当您需要管理已购买的云服务器（如物理服务器、裸机云、VPS等），或查看产品状态、续费信息时，可以通过以下<strong>三种方式</strong>在 RakSmart 客户中心快速定位您的产品。</p><ol><li><strong>快捷搜索</strong>：通过主机名或主IP直接搜索</li><li><strong>首页快捷入口</strong>：通过“我的订单”或“我的服务”快速查看</li><li><strong>产品管理导航</strong>：按产品类型、地区、状态筛选查找</li></ol><p>下面将为您详细介绍每种方法的具体操作步骤。</p><hr><h2 id="方法一-快捷搜索-最快速" tabindex="-1">方法一：快捷搜索（最快速） <a class="header-anchor" href="#方法一-快捷搜索-最快速" aria-label="Permalink to &quot;方法一：快捷搜索（最快速）&quot;">​</a></h2><p>如果您记得机器的<strong>主机名</strong>或<strong>主IP地址</strong>，可以使用此方法直接定位。</p><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li><p><strong>登录RakSmart客户后台中心</strong></p></li><li><p>在页面<strong>右上角</strong>找到搜索栏（显示“Q 请输入”的输入框）</p><p><img src="'+n+'" alt=""></p></li><li><p>输入您机器的<strong>主IP地址</strong>或<strong>主机名</strong></p><ul><li>例如：输入 <code>192.168.1.100</code> 或 <code>sv-xxxxx</code></li></ul></li><li><p>系统会自动显示匹配的<strong>产品订单</strong></p></li><li><p>点击搜索结果中的订单，即可进入该机器的产品页面</p></li></ol><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><ul><li>您清楚记得机器的IP或主机名</li><li>需要快速进入特定机器的管理页面</li></ul><hr><h2 id="方法二-通过客户中心首页查找" tabindex="-1">方法二：通过客户中心首页查找 <a class="header-anchor" href="#方法二-通过客户中心首页查找" aria-label="Permalink to &quot;方法二：通过客户中心首页查找&quot;">​</a></h2><p>如果您刚登录后台，可以通过首页的快捷入口查看当前活跃的订单。</p><h3 id="通过-我的订单-当前订单-查看" tabindex="-1">通过“我的订单 - 当前订单”查看 <a class="header-anchor" href="#通过-我的订单-当前订单-查看" aria-label="Permalink to &quot;通过“我的订单 - 当前订单”查看&quot;">​</a></h3><ol><li><p>登录后进入<strong>客户中心首页</strong></p><p><img src="'+e+'" alt=""></p></li><li><p>在首页找到**“我的订单”**区域</p></li><li><p>查看**“当前订单”<strong>，即可看到所有</strong>活跃状态**的订单列表</p></li><li><p>在订单列表中：</p><ul><li>点击具体<strong>产品类</strong>（如“物理服务器”），可进入该产品的详情页</li><li>或者点击“我的服务”查看所有活跃产品</li></ul></li></ol><h3 id="适用场景-1" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景-1" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><ul><li>想快速查看所有活跃产品</li><li>不记得具体IP或主机名，需要浏览订单列表</li></ul><hr><h2 id="方法三-通过产品管理导航查找-最全面" tabindex="-1">方法三：通过产品管理导航查找（最全面） <a class="header-anchor" href="#方法三-通过产品管理导航查找-最全面" aria-label="Permalink to &quot;方法三：通过产品管理导航查找（最全面）&quot;">​</a></h2><p>如果您需要按<strong>产品类型、地区、状态</strong>等条件筛选查找，可以使用此方法。</p><h3 id="_1-进入产品管理" tabindex="-1">1. 进入产品管理 <a class="header-anchor" href="#_1-进入产品管理" aria-label="Permalink to &quot;1. 进入产品管理&quot;">​</a></h3><p>在左侧导航栏找到**“产品管理”**，根据您购买的产品类型选择：</p><ul><li><p><strong>物理服务器</strong></p></li><li><p><strong>裸机云</strong></p></li><li><p><strong>VPS</strong></p><p><img src="'+l+'" alt=""></p></li></ul><h3 id="_2-按地区筛选" tabindex="-1">2. 按地区筛选 <a class="header-anchor" href="#_2-按地区筛选" aria-label="Permalink to &quot;2. 按地区筛选&quot;">​</a></h3><p>进入对应产品页面后，您可以看到<strong>地区筛选</strong>选项：</p><table tabindex="0"><thead><tr><th>地区</th><th>可用选项</th></tr></thead><tbody><tr><td><strong>美洲</strong></td><td>硅谷、洛杉矶、西雅图等</td></tr><tr><td><strong>亚洲</strong></td><td>新加坡、香港、日本、韩国等</td></tr><tr><td><strong>欧洲</strong></td><td>法兰克福等</td></tr></tbody></table><p>选择对应地区，即可查看该区域下的所有机器。</p><h3 id="_3-按状态筛选" tabindex="-1">3. 按状态筛选 <a class="header-anchor" href="#_3-按状态筛选" aria-label="Permalink to &quot;3. 按状态筛选&quot;">​</a></h3><p>选择地区后，您还需要通过<strong>状态筛选</strong>快速定位特定状态的机器：</p><table tabindex="0"><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><strong>全部</strong></td><td>显示所有状态的机器</td></tr><tr><td><strong>有效的</strong></td><td>正常运行中的机器</td></tr><tr><td><strong>审核中</strong></td><td>新购或操作变更待审核</td></tr><tr><td><strong>已暂停</strong></td><td>因欠费或其他原因暂停</td></tr><tr><td><strong>已终止</strong></td><td>已删除或过期</td></tr><tr><td><strong>已取消</strong></td><td>订单已取消</td></tr></tbody></table><h3 id="_4-查看产品列表" tabindex="-1">4. 查看产品列表 <a class="header-anchor" href="#_4-查看产品列表" aria-label="Permalink to &quot;4. 查看产品列表&quot;">​</a></h3><p>筛选后，页面会显示符合条件的产品列表，包含以下信息：</p><ul><li><strong>产品/服务</strong>：产品配置信息</li><li><strong>主机名称</strong>：机器的主机名</li><li><strong>IP</strong>：机器的IP地址（部分产品显示）</li><li><strong>价格</strong>：产品价格</li><li><strong>下次付款日期</strong>：续费日期</li><li><strong>状态</strong>：当前运行状态</li><li><strong>自动续费</strong>：是否开启自动续费</li></ul><p>点击具体产品，即可进入该机器的管理面板进行重装系统、重启、查看监控等操作。</p><hr><h2 id="各产品类型查找路径汇总" tabindex="-1">各产品类型查找路径汇总 <a class="header-anchor" href="#各产品类型查找路径汇总" aria-label="Permalink to &quot;各产品类型查找路径汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品类型</th><th>查找路径</th></tr></thead><tbody><tr><td><strong>物理服务器</strong></td><td>产品管理 → 物理服务器 → 选择地区/状态筛选</td></tr><tr><td><strong>裸机云</strong></td><td>产品管理 → 裸机云 → 选择地区/状态筛选</td></tr><tr><td><strong>VPS</strong></td><td>产品管理 → VPS → 选择地区/状态筛选</td></tr><tr><td><strong>所有活跃产品</strong></td><td>客户中心首页 → 我的服务</td></tr><tr><td><strong>当前订单</strong></td><td>客户中心首页 → 我的订单 → 当前订单</td></tr></tbody></table><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：为什么我在产品管理里看不到任何机器？</strong> A：请检查：① 是否选择了正确的产品类型；② 地区筛选是否包含您机器的所在地；③ 状态筛选是否选择了“全部”或“有效的”；④ 确认您登录的账号是否是该产品的所有者。</p><p><strong>Q：搜索栏输入IP后没有显示结果？</strong> A：请确认：① IP地址输入是否正确；② 该IP是否属于您当前登录的账号。</p><p><strong>Q：我的机器显示“审核中”是什么意思？</strong> A：表示您新购的机器正在上架安装中，审核通过后状态会变为“有效的”。</p><p><strong>Q：如何区分物理服务器和裸机云？</strong> A：物理服务器是纯物理机，裸机云是具备云化功能的物理机，两者在产品管理中是分开的菜单，请根据您购买的产品类型选择对应入口</p>',44)])])}const P=r(d,[["render",i]]);export{_ as __pageData,P as default};
